function extract($, ctx) {
  const items = [];
  const seen = new Set();

  // Try to extract from JSON-LD first
  $('script[type="application/ld+json"]').each((_, el) => {
    let data;
    try {
      data = JSON.parse($(el).text());
    } catch (e) {
      return;
    }
    const menuList = Array.isArray(data) ? data : [data];
    for (const obj of menuList) {
      if (!obj || obj["@type"] !== "Menu") continue;
      const sections = obj.hasMenuSection || [];
      for (const sec of sections) {
        const sectionName = sec.name ? String(sec.name).trim() : null;
        const menuItems = sec.hasMenuItem || [];
        for (const it of menuItems) {
          const name = it.name ? String(it.name).trim() : "";
          if !name) continue;
          const description = it.description ? String(it.description).trim() : null;
          let priceNum = null;
          if (it.offers && typeof it.offers.price !== "undefined") {
            priceNum = parsePrice(String(it.offers.price));
          }
          const key = `${sectionName}|${name}|${description}|${priceNum}`;
          if (seen.has(key)) continue;
          seen.add(key);
          items.push({
            section: sectionName,
            name: name,
            description: description,
            price: priceNum
          });
        }
      }
    }
  });

  // Fallback to DOM extraction if JSON-LD yielded nothing
  if (items.length === 0) {
    const $menu = $('#menu-root');
    if ($menu.length) {
      $menu.find('.menu-group').each((_, sectEl) => {
        const $sect = $(sectEl);
        const sectionTitle = $sect.find('.menu-group__title').first().text().trim() || null;
        $sect.find('.dish').each((_, dishEl) => {
          const $dish = $(dishEl);
          const nameEl = $dish.find('.dish__name');
          const name = nameEl ? cleanText(nameEl.text()) : "";
          if (!name) return;
          const descEl = $dish.find('.dish__desc');
          const description = descEl ? cleanText(descEl.text()) : null;
          const priceEl = $dish.find('.dish__price');
          const price = priceEl ? parsePrice(priceEl.text()) : null;
          items.push({
            section: sectionTitle,
            name: name,
            description: description,
            price: price
          });
        });
      });
    }
  }

  return items;
}
